files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  line-height: 1;
  background-color: #5f0dee;
}

.login__link {
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: max-content;
  border: 1px solid;
  padding: 15px 30px;
  font-family: inherit;
  font-weight: 800;
  font-size: 12px;
  text-decoration: none;
  text-transform: uppercase;
  background-color: #ffc802;
}

.login__icon {
  width: 2em;
  /* Стили пишите здесь */
}

@media(min-width: 620px) {
  .login__link {
    font-size: 16px;
  }
}

@media(min-width: 980px) {
  .login__link {
    font-size: 18px;
  }
}

@media(min-width: 1280px) {
  .login__link {
    font-size: 22px;
  }
}

@media(min-width: 1440px) {
  .login__link {
    font-size: 24px;
  }
}
